@OptIn(ExperimentalMaterial3Api::class) // 标记此函数使用了实验性的 Material3 API
@Composable // 声明这是一个 Jetpack Compose 的可组合函数
fun ConversationListScreen(navController: NavController) { // 定义会话列表屏幕，接收一个 NavController 用于导航

    // ✅ 给明确类型，避免 items() 推断 T 失败
    // 使用 remember 记住排序后的会话列表，只有当会话数量或置顶状态变化时才重新计算
    val sortedConversations: List<Conversation> = remember(       //使用remember函数 计算出key值判断状态是否改变
        DataSource.conversations.size, // 会话列表的大小
        DataSource.conversations.map { it.isPinned } // 每个会话的置顶状态  状态改变从而key2改变
    ) {
        DataSource.conversations.sortedWith(compareByDescending { it.isPinned }) // 按置顶状态降序排序 sortedwith是排序函数接受一个比较器来进行自定义排序
    }

    Scaffold( // 使用 Material3 的 Scaffold 脚手架布局
        topBar = { // 定义顶部应用栏
            TopAppBar( // 使用 TopAppBar 组件
                title = { Text("消息") }, // 设置标题为“消息”
                actions = { // 定义右侧的操作按钮
                    IconButton(onClick = { // 添加一个图标按钮
                        var newFriendNumber = 1 // 初始化新朋友的编号
                        var newFriendName = "新朋友" // 初始化新朋友的默认名称
                        while (DataSource.conversations.any { it.name == newFriendName }) { // 循环检查名称是否已存在
                            newFriendNumber++ // 如果存在，编号加一
                            newFriendName = "新朋友 $newFriendNumber" // 更新名称
                        }
                        DataSource.getMessagesForConversation(newFriendName) // 为新朋友创建一个会话（如果需要）
                        navController.navigate("conversation_detail/$newFriendName") // 导航到新朋友的会话详情页 根据传入路由地址来跳转到会话详情页
                    }) {
                        Icon(Icons.Default.Add, contentDescription = "添加新会话") // 设置按钮图标为“添加”，并提供内容描述
                    }
                }
            )
        }
    ) { innerPadding -> // Scaffold 的内容区域，innerPadding 用于处理 TopAppBar 遮挡
        LazyColumn( // 使用 LazyColumn 创建一个垂直滚动的列表   懒加载 只有进入可视区域后才可以渲染
            modifier = Modifier
                .fillMaxSize() // 填充整个可用空间
                .padding(innerPadding) // 应用内边距，避免内容被 TopAppBar 遮挡
        ) {
            items( // 定义列表项
                items = sortedConversations, // 列表的数据源是排序后的会话列表
                key = { it.name } // 为每个列表项设置一个唯一的 key，提高性能和稳定性
            ) { conversation -> // 遍历每个会话数据
                ConversationListItem( // 为每个会话创建一个列表项 UI
                    conversation = conversation, // 传入会话数据
                    onClick = { // 定义点击事件
                        navController.navigate("conversation_detail/${conversation.name}") // 点击后导航到对应的会话详情页
                    }
                )
            }
        }
    }
}

@Composable // 声明这是一个 Jetpack Compose 的可组合函数
fun ConversationListItem( // 定义单个会话列表项的 UI
    conversation: Conversation, // 接收会话数据 是函数的参数
    onClick: () -> Unit // 接收点击事件的回调 定义了一个点击事件的回调函数
) {
    val scope = rememberCoroutineScope() // 获取一个协程作用域，用于启动协程加载会话相关数据/动画等操作
    val density = LocalDensity.current // 获取当前的屏幕密度，用于 dp 和 px 之间的转换 不同设备密度不同实现页面正确适配

    // 两个按钮总宽度（置顶80 + 删除80）
    // 使用 remember 记住计算出的像素值，避免重复计算
    val openPx = remember(density) { with(density) { 160.dp.toPx() } } // 将 160.dp 转换为像素值  将屏幕密度转化为像素值 统一！

    // ✅ 用 Animatable 自己管理横向偏移：范围 [-openPx, 0]
    // 创建一个 Animatable 值来控制横向偏移，初始值为 0
    val offsetX = remember { Animatable(0f) }    //实现动画效果 改变偏移值 保证动画过程中偏移值的连续性和一致性。 支持拖拽跟手松手吸附点击收回动画丝滑！！

    fun clamp(x: Float): Float = x.coerceIn(-openPx, 0f) // 定义一个clamp函数，将偏移量限制在 [-openPx, 0f] 范围内 最多打开到按钮全部露出

    Box( // 使用 Box 布局，允许子组件堆叠
        modifier = Modifier
            .fillMaxWidth() // 填充父容器的宽度
            .padding(vertical = 4.dp) // 设置垂直方向的内边距
    ) {
        // 背景按钮层（在右侧） 实现会话列表交互功能
        Row( // 使用 Row 布局将按钮水平排列
            modifier = Modifier
                .fillMaxHeight() // 填充父容器的高度
                .align(Alignment.CenterEnd), // 对齐到父容器的末尾（右侧）
            verticalAlignment = Alignment.CenterVertically // 子项在垂直方向上居中对齐
        ) {
            // 置顶按钮
            Box( // 使用 Box 替代 IconButton 以获得完整的高度控制
                modifier = Modifier
                    .width(80.dp) // 设置按钮宽度为 80.dp
                    .fillMaxHeight() // 填充父容器的高度，使按钮高度满满的
                    .background(MaterialTheme.colorScheme.tertiaryContainer) // 设置背景颜色
                    .clickable { // 定义点击事件
                        conversation.isPinned = !conversation.isPinned // 切换会话的置顶状态
                        scope.launch { // 启动一个协程
                            offsetX.animateTo(0f, tween(180)) // 以动画方式将卡片移回原位 targetvalue动画目标值 动画规格、动画持续时间Tween 是基于时间的渐变动画，在起始值和结束值间创建平滑过渡，通过设定动画时长、延迟时间和缓动曲线来定义动画变化过程。
                        }
                    },
                contentAlignment = Alignment.Center // 内容居中对齐
            ) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) { // 使用 Column 将图标和文字垂直排列
                    Icon(Icons.Filled.PushPin, contentDescription = "置顶") // 显示置顶图标
                    Text("置顶", fontSize = 12.sp) // 显示"置顶"文字
                }
            }

            // 删除按钮
            Box( // 使用 Box 替代 IconButton 以获得完整的高度控制
                modifier = Modifier
                    .width(80.dp) // 设置按钮宽度为 80.dp
                    .fillMaxHeight() // 填充父容器的高度，使按钮高度满满的
                    .background(MaterialTheme.colorScheme.errorContainer) // 设置背景颜色
                    .clickable { // 定义点击事件
                        DataSource.conversations.remove(conversation) // 从数据源中删除此会话
                    },
                contentAlignment = Alignment.Center // 内容居中对齐
            ) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) { // 使用 Column 将图标和文字垂直排列
                    Icon(Icons.Filled.Delete, contentDescription = "删除") // 显示删除图标
                    Text("删除", fontSize = 12.sp) // 显示"删除"文字
                }
            }
        }

        // 前景卡片层（可拖拽）
        Card( // 使用 Card 组件作为前景 让每个聊天都在一个框框里！！！！！ 卡片容器组件
            modifier = Modifier
                .fillMaxWidth() // 填充父容器的宽度
                .height(72.dp) // 设置卡片固定高度为 72dp，使后面按钮能够完全填满
                .offset { IntOffset(offsetX.value.roundToInt(), 0) } // 根据 offsetX 的值来偏移卡片位置
                .draggable( // 使卡片可以水平拖动
                    orientation = Orientation.Horizontal, // 设置拖动方向为水平
                    state = rememberDraggableState { delta -> // 记住拖动状态
                        // delta>0 向右拖，delta<0 向左拖
                        scope.launch { // 在协程中处理拖动
                            offsetX.snapTo(clamp(offsetX.value + delta)) // 立即更新偏移量，并限制在范围内 snapto 拖拽跟手
                        }
                    },
                    onDragStopped = { velocity -> // 拖动停止时的回调函数
                        // ✅ 松手后自动“吸附”：超过一半就打开，否则关闭
                        scope.launch { // 在协程中处理吸附动画
                            // 判断是否应该打开：偏移量超过一半，或者向左的快速滑动
                            val shouldOpen = abs(offsetX.value) > openPx * 0.5f || velocity < -800f    //偏移量大于多少 速度小于800 负数因为是负方向
                            val target = if (shouldOpen) -openPx else 0f // 设置目标位置（完全打开或完全关闭）
                            offsetX.animateTo(target, tween(180)) // 以动画方式移动到目标位置
                        }
                    }
                )
                .clickable { // 给卡片添加点击事件
                    // 如果已经打开，点一下先收回；否则进入详情
                    scope.launch { // 在协程中处理点击逻辑
                        if (offsetX.value != 0f) offsetX.animateTo(0f, tween(160)) // 如果已侧滑，则收回
                        else onClick() // 否则执行传入的 onClick 回调（进入详情页）
                    }
                }
        ) {
            Row( // 使用 Row 布局排列卡片内容，从左到右依次为头像、名字和消息摘要、时间和未读数
                modifier = Modifier.padding(16.dp), // 设置内边距
                verticalAlignment = Alignment.CenterVertically // 子项在垂直方向上居中对齐
            ) {
                AsyncImage( // 显示会话对方的圆形头像
                    model = conversation.avatar, // 头像资源，可以是 drawable 或 URI
                    contentDescription = "对方头像", // 内容描述，用于无障碍访问
                    modifier = Modifier // 修饰符
                        .size(40.dp) // 设置头像大小为 40dp
                        .clip(CircleShape), // 裁剪为圆形
                    contentScale = ContentScale.Crop // 缩放模式为裁剪，填满容器
                )

                Spacer(modifier = Modifier.width(8.dp)) // 添加水平间隔，距离头像 8dp

                Column(modifier = Modifier.weight(1f)) { // 中间内容区域，占据剩余空间，包含名字和消息摘要
                    Row(verticalAlignment = Alignment.CenterVertically) { // 名字和置顶图标行
                        Text( // 显示会话名称
                            text = conversation.name, // 会话名字
                            fontWeight = FontWeight.Bold, // 字体加粗
                            fontSize = 16.sp // 字体大小 16sp
                        )
                        if (conversation.isPinned) { // 如果会话已置顶
                            Spacer(modifier = Modifier.width(6.dp)) // 添加间隔
                            Icon( // 显示置顶图标
                                imageVector = Icons.Filled.PushPin, // 置顶图标
                                contentDescription = "已置顶", // 内容描述
                                modifier = Modifier.size(16.dp), // 图标大小
                                tint = MaterialTheme.colorScheme.primary // 图标颜色
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(4.dp)) // 添加垂直间隔，距离名字 4dp

                    val summaryText = if (conversation.draft.isNotEmpty()) { // 判断是否有草稿
                        "[草稿] ${conversation.draft}" // 如果有，显示草稿内容
                    } else {
                        conversation.messages.lastOrNull()?.content ?: "还没有消息" // 否则显示最后一条消息，如果没有消息则显示默认文本
                    }

                    val summaryColor = if (conversation.draft.isNotEmpty()) { // 判断是否有草稿
                        MaterialTheme.colorScheme.error // 如果有，摘要文本颜色使用错误提示色
                    } else {
                        Color.Gray // 否则使用灰色
                    }

                    Text( // 显示消息摘要文本
                        text = summaryText, // 摘要内容
                        color = summaryColor, // 设置文本颜色
                        fontSize = 14.sp, // 设置字体大小 14sp
                        maxLines = 1, // 最多显示一行
                        overflow = TextOverflow.Ellipsis // 超出部分显示省略号
                    )
                }

                Spacer(modifier = Modifier.width(16.dp)) // 添加水平间隔，距离中间内容 16dp

                Column(horizontalAlignment = Alignment.End) { // 右侧时间与未读数区域，对齐到末尾
                    Text("12:11", color = Color.Gray, fontSize = 12.sp) // 显示消息时间（这里是硬编码的）
                    Spacer(modifier = Modifier.height(4.dp)) // 添加垂直间隔
                    if (conversation.unreadCount > 0) { // 如果有未读消息
                        Badge { Text(text = "${conversation.unreadCount}") } // 使用 Badge 显示未读消息数量
                    }
                }
            }
        }
    }
}

package com.example.screenshotoftaskmanager // 包名声明

import android.os.Bundle // 导入 Bundle 类，用于处理 Activity 状态就是装数据的小容器 可以用来保存/恢复状态 “包”
import androidx.activity.ComponentActivity // 导入基础 Activity 类   “支持生命周期、SavedState、Activity Result 等现代组件。”
import androidx.activity.compose.setContent // 导入 Compose 内容设置函数Compose 的关键入口：把“Compose UI 树”放进 Activity 的窗口里。
import androidx.activity.enableEdgeToEdge // 导入全屏沉浸式体验函数开启边到边显示
import androidx.compose.foundation.layout.fillMaxSize // 导入全屏填充修饰符 全屏
import androidx.compose.material3.MaterialTheme // 导入 Material3 主题样式库
import androidx.compose.material3.Surface // 导入 Surface 容器组件  底板容器 设置背景色 阴影形状 做整体页面根容器
import androidx.compose.runtime.Composable // 导入可组合函数注解 标记函数是可组合函数
import androidx.compose.ui.Modifier // 导入修饰符接口  Compose的装修工具：尺寸边距点击背景对齐……
import androidx.compose.ui.tooling.preview.Preview // 导入预览模块
import androidx.core.splashscreen.SplashScreen.Companion.installSplashScreen // 导入官方启动页安装函数 启动页面
import androidx.lifecycle.lifecycleScope // 导入生命周期范围，用于开启协程  避免内存泄漏
import androidx.navigation.NavType // 导入导航参数类型
import androidx.navigation.compose.NavHost // 导入导航宿主
import androidx.navigation.compose.composable // 导入导航路由定义函数
import androidx.navigation.compose.rememberNavController // 导入导航控制器记录函数
import androidx.navigation.navArgument // 导入导航参数定义函数
import com.example.screenshotoftaskmanager.ui.ConversationDetailScreen // 导入聊天详情页
import com.example.screenshotoftaskmanager.ui.LoginScreen // 导入登录页
import com.example.screenshotoftaskmanager.ui.MainScreen // 导入主屏幕
import com.example.screenshotoftaskmanager.ui.OnboardingScreen // 导入引导页
import com.example.screenshotoftaskmanager.ui.RegisterScreen // 导入注册页
import com.example.screenshotoftaskmanager.ui.theme.ScreenshotofTaskManagerTheme // 导入项目主题
import kotlinx.coroutines.delay // 导入延迟函数
import kotlinx.coroutines.launch // 导入协程开启函数 启动一个协程 异步任务：任务在后台执行不阻塞当前程序

class MainActivity : ComponentActivity() { // MainActivity 类定义

    // 定义一个变量，用于控制启动页是否应该继续显示在屏幕上（默认初始为 true）
    private var keepSplashScreen = true

    override fun onCreate(savedInstanceState: Bundle?) { // onCreate 生命周期方法

        // 1. 安装启动页，并获取启动页对象
        val splashScreen = installSplashScreen() //调用官方splash api 系统启动时就会先显示启动页 返回一个splashscreen对象

        // 2. 设置启动页保持在屏幕上的条件：只要 keepSplashScreen 是 true，启动页就不消失
        splashScreen.setKeepOnScreenCondition { keepSplashScreen }

        // ✅ 修改点：在生命周期协程中执行延时操作
        // 旋转 1s + 停顿 0.7s = 1.7s。转两圈并停顿两次总共需要 3.4s (3400ms)
        lifecycleScope.launch {
            delay(3400) // 强制让启动页在此停留 3400 毫秒 (3.4 秒)
            keepSplashScreen = false // 3.4 秒时间到，将变量设为 false，启动页平滑消失，进入欢迎页
        }

        super.onCreate(savedInstanceState) // 调用父类初始化

        enableEdgeToEdge() // 开启全屏边缘到边缘的沉浸式体验

        setContent { // 开始设置 Compose 渲染内容
            ScreenshotofTaskManagerTheme { // 应用项目全局主题
                Surface(  //一个全新底板容器
                    modifier = Modifier.fillMaxSize(), // 让容器占满全屏
                    color = MaterialTheme.colorScheme.background // 使用主题中的背景颜色 好处：切深色模式时自动适配
                ) {
                    TaskManagerApp() // 加载主导航应用
                }
            }
        }
    }
}

@Composable
fun TaskManagerApp() { // 应用主导航函数
    val navController = rememberNavController() // 创建导航控制器
    NavHost(navController = navController, startDestination = "onboarding") { // 定义导航宿主和起始页
        composable("onboarding") { // 引导页路由
            OnboardingScreen(navController = navController) // 渲染引导页
        }
        composable("login") { // 登录页路由
            LoginScreen(navController = navController) // 渲染登录页
        }
        composable("register") { // 注册页路由
            RegisterScreen(navController = navController) // 渲染注册页
        }
        composable("conversation_list") { // 会话列表页路由
            MainScreen(mainNavController = navController) // 渲染主界面（包含底部导航） Mainscreen作为主界面
        }
        composable(
            route = "conversation_detail/{conversationName}", // 聊天详情路由，带参数 动态路由模板
            arguments = listOf(navArgument("conversationName") { type = NavType.StringType }) // 定义字符串类型的参数 声明参数列表
        ) { backStackEntry ->    //返回栈条录
            val conversationName = backStackEntry.arguments?.getString("conversationName") ?: "" // 取出参数值
            ConversationDetailScreen(navController = navController, conversationName = conversationName) // 渲染详情页
        }
    }
}

@Preview(showBackground = true) // 预览模式设置
@Composable
fun AppPreview() { // 预览组件函数
    ScreenshotofTaskManagerTheme { // 应用主题
        TaskManagerApp() // 预览整体应用
    }
}

